mapper.select:
select

from CHB_TRANS_MONTH


        DATE_FORMAT(CHB_SUBMIT_DEADLINE,'%Y-%m-%d') >= #{submitDeadLineStart,jdbcType=VARCHAR}


        and DATE_FORMAT(CHB_SUBMIT_DEADLINE,'%Y-%m-%d') <= #{submitDeadLineEnd,jdbcType=VARCHAR}



            #{item,jdbcType=VARCHAR}




            #{item,jdbcType=VARCHAR}




            #{item,jdbcType=VARCHAR}



        and DATE_FORMAT(STATUS_DATE,'%Y-%m-%d') >= #{statusDateStart,jdbcType=VARCHAR}


        and DATE_FORMAT(STATUS_DATE,'%Y-%m-%d') <= #{statusDateEnd,jdbcType=VARCHAR}


        and DATE_FORMAT(STATUS_DATE,'%Y-%m-%d') >= #{submitDateStart,jdbcType=VARCHAR}


        and DATE_FORMAT(STATUS_DATE,'%Y-%m-%d') <= #{submitDateEnd,jdbcType=VARCHAR}


        and TERMID >= #{termidDateStart,jdbcType=VARCHAR}


        and TERMID <= #{termidDateEnd,jdbcType=VARCHAR}



            #{submitFeedbackStatus,jdbcType=VARCHAR}



        and SEND_STATUS = #{sendStatus,jdbcType=VARCHAR}


        and TERMID = #{termid,jdbcType=VARCHAR}


        and DATE_FORMAT(ENDDATE,'%Y-%m') = #{enddate,jdbcType=VARCHAR}


ORDER BY STATUS_DATE

mapper.insert:
insert into CHB_TRANS_MONTH ( REPORTUUID, TERMID, REPORTTYPE, STARTDATE, ENDDATE, ISSUE_PARTY_ID, ISSUE_PARTY_NAME, REPORTFREQU, SUBMIT_TIME, CHB_SUBMIT_DEADLINE, SUBMIT_DEADLINE, SUBMIT_FEEDBACK_STATUS, STATUS, SEND_STATUS, STATUS_DATE, CREATE_USER, CREATE_TIME, UPDATE_USER, UPDATE_TIME, ORG_CODE, DEPT_CODE, CREATE_DEPT) select REPORTUUID, TERMID, REPORTTYPE, STARTDATE, ENDDATE, ISSUE_PARTY_ID, ISSUE_PARTY_NAME, REPORTFREQU, SUBMIT_TIME, CHB_SUBMIT_DEADLINE, SUBMIT_DEADLINE,
SUBMIT_FEEDBACK_STATUS, STATUS, SEND_STATUS, STATUS_DATE, CREATE_USER, his.CREATE_TIME,
UPDATE_USER, UPDATE_TIME, ORG_CODE, DEPT_CODE, CREATE_DEPT from CHB_TRANS_MONTH_HIS his INNER join ( SELECT max(CREATE_TIME) CREATE_TIME from CHB_TRANS_MONTH_HIS
TERMID IN
#{regist.termid,jdbcType=VARCHAR}
) maxtime on his.CREATE_TIME=maxtime.CREATE_TIME

mapper.delete:
delete from CHB_TRANS_MONTH_HIS his where his.CREATE_TIME=(select CREATETIME from ( SELECT max(CREATE_TIME) as CREATETIME from CHB_TRANS_MONTH_HIS
TERMID IN
#{regist.termid,jdbcType=VARCHAR}
) tmp)

mapper.update:
update CHB_TRANS_MONTH
SEND_STATUS = '01', UPDATE_TIME = now(), SUBMIT_TIME = null, SUBMIT_FEEDBACK_STATUS = null
REPORTUUID = #{dto.reportuuid}

